<dl class="totals"><div><dt>Subtotal</dt><dd><?= money($cart['subtotal']) ?></dd></div>
<?php if(!empty($cart['welcome_discount'])): ?><div class="welcome-saving"><dt>New Customer Welcome Discount — <?= (int)$cart['welcome']['percentage'] ?>%</dt><dd>−<?= money($cart['welcome_discount']) ?></dd></div><?php endif ?>
<?php foreach($cart['applied_offers']??[] as $applied): ?><div class="welcome-saving"><dt><?= e($applied['title']) ?></dt><dd>−<?= money($applied['amount']) ?></dd></div><?php endforeach ?>
<?php if($cart['discount']): ?><div><dt>Discounted subtotal</dt><dd><?= money($cart['discounted_subtotal']) ?></dd></div><?php endif ?>
<div><dt>Delivery</dt><dd><?= in_array($cart['delivery_details']['status'],['ready','minimum'],true)?($cart['delivery']?money($cart['delivery']):'Free Delivery'):($cart['delivery_details']['status']==='pending'?'Choose delivery area':'Unavailable') ?></dd></div><?php if($cart['tax']): ?><div><dt>Tax</dt><dd><?= money($cart['tax']) ?></dd></div><?php endif ?><div class="total"><dt><?= $cart['delivery_details']['status']==='ready'?'Total':($cart['delivery_details']['status']==='minimum'?'Estimated total (minimum not met)':'Subtotal so far (delivery pending)') ?></dt><dd><?= money($cart['total']) ?></dd></div></dl>
<?php if(!empty($cart['welcome'])): $offer=$cart['welcome']; ?><div class="welcome-cart-note" data-welcome-status="<?= e($offer['status']) ?>">
<?php if($offer['status']==='active'): ?><small>Your <?= (int)$offer['percentage'] ?>% welcome offer ends <?= e(welcome_expiry_label($offer['expires_at'])) ?>. Full-priced pieces only; excludes sale items, delivery and tax. We apply the better of welcome or promotional savings, without combining them.</small><?php if(!$cart['welcome_discount']): ?><p>This order will end first-order eligibility without using the welcome discount. Promotional savings apply when they save more.</p><?php endif ?>
<?php elseif($offer['status']==='expired'): ?><small>Your welcome offer has ended. The totals above do not include it.</small><?php else: ?><small>Your welcome offer has already been redeemed.</small><?php endif ?></div><?php endif ?>

<?php $delivery=$cart['delivery_details'];if($delivery['mode']!=='legacy'): ?><div class="delivery-quote-note" data-delivery-status="<?= e($delivery['status']) ?>"><?php if($delivery['name']): ?><p><strong>Delivery area:</strong> <?= e($delivery['name']) ?></p><?php endif ?><?php if($delivery['message']): ?><p class="<?= $delivery['status']==='ready'?'muted':'error-text' ?>"><?= e($delivery['message']) ?></p><?php endif ?><?php if($delivery['status']==='ready'): ?><p><?= e($delivery['estimate']) ?></p><p><?= e($delivery['notes']) ?></p><?php endif ?></div><?php endif ?>
